fun quarter(x: Int, z: Int): Int {
    val ax = abs(x)
    val az = abs(z)
    return when {
        ax >= az && x >= 0 -> 0
        az > ax && z >= 0 -> 1
        ax > az -> 2
        else -> 3
    }
}

return when (quarter(x, z)) {
    0 -> RED
    1 -> YELLOW
    2 -> BLUE
    else -> LIME
}
